async function ingestAndOpenCase(
  input: { triggerMode: string; coverDate: string; planType: string; stations: Power_Station[];
           weather: Weather_Data[]; hydrology: Hydrology_Data[]; gzl: Grid_Interface_Plan;
           operatorRole: Role; context: Operating_Context }
): Promise<{ dispatchCase: Dispatch_Case; ingested: Business_System }> {
  // step1 ingestSourceData —— 慧采唯一入口接入并 96 点时标对齐 (rule 1 唯一入口 / rule 2 真相源)
  // 智调绝不直连外部源:SCADA/气象/水文/关口GZL/市场出清一律经慧采落库
  const ingested = await huicai.ingest({                 // 慧采-SCADA/气象/水文/关口/市场接入
    scada: true, weather: input.weather, hydrology: input.hydrology,
    gzl: input.gzl, market: true,
  });
  assertWrittenToOwnerSystem(ingested);                  // rule 2 谁写谁读,禁止硬改他系统数据
  const aligned = huicai.alignTo96Points(ingested);      // 96 点逐时段时标对齐 → DATA_INGESTED
  emit("DATA_INGESTED", aligned);

  // step2 shiftPreReview —— 值班调度员班前"四看"人工打底(来水/可用容量/关口GZL/市场出清)
  const preReview = manualShiftReview(input.operatorRole, {
    inflow: input.hydrology, capacity: queryEquipmentAvailable(input.stations),
    gzl: input.gzl, market: aligned.market,
  });                                                     // 人工常识打底,不由智调代研判

  // step3 openDispatchCase —— 智调开案得 DS 号,状态置 DRAFT
  const prior = findUnconfirmedCase(input.stations, input.coverDate);
  if (prior) markSuperseded(prior, "VOID");               // 同覆盖时段同电站重复开案,前案 superseded→VOID
  const dispatchCase = openCase({                         // 智调-案件管理
    coverDate: input.coverDate, planType: input.planType,
    stations: input.stations.map(s => s.power_station_id),
    operatingContextId: input.context.operating_context_id,
    ingestBatchId: aligned.batchId, createdBy: input.operatorRole.role_id,
    status: "DRAFT", traceLog: appendPreReview(preReview),
  });
  return { dispatchCase, ingested: aligned };
}

async function interpretData(
  ctx: { caseId: string; triggerEvent: "DATA_INGESTED" | "MANUAL_REVIEW_DECIDED"; payload?: string },
  wx: WeatherData[],            // Weather_Data 气象批次
  hy: HydrologyData[],          // Hydrology_Data 水文批次
  cascade: PowerStation[],      // Power_Station 梯级拓扑/滞时
): Promise<{ event?: "DATA_INTERPRETED"; result?: InterpretationResult }> {
  // 退回重走:MANUAL_REVIEW_DECIDED 载荷=RETURNED_FOR_REVISION 时案件已回 DRAFT,从解释起重跑
  // 域边界:数据均经慧采(Business_System)落库,严禁直连外部源(rule 1)

  // 步骤1 runDataQC —— 气象六道关(rule 3)、水文七道关含水量平衡/梯级一致性硬校验(rule 4 / CR-HYD-04)
  const wxQc = runWeatherQC(wx);                 // ①时标②缺测③物理范围④多源一致⑤连续性⑥完整性置信
  const hyQc = runHydrologyQC(hy, cascade);      // 多出④水量平衡 入库=出库±蓄变 ⑤梯级 上级出库≈下级入库±区间±滞时
  if (hyQc.imbalance) markSuspectAndProbe(hyQc); // rule 4:配不平标存疑查表计/探头,严禁手工凑数做平
  const blocked = [...wxQc.failed, ...hyQc.failed];
  if (blocked.length) {                          // 不合格拦截、不进解释、不报事件
    notify("新能源预测专责:赵敏", "告警铃", blocked);
    if (hyQc.failed.length) alertProbeAnomaly(hyQc.failed); // 水文不合格主动预警(探头被挡/断面冲毁前兆)
  }
  if (!wxQc.passed.length && !hyQc.passed.length) return {}; // 全不合格则不产出 DATA_INTERPRETED

  // 步骤2 interpretResourceSignal —— 合格气象→风光资源信号(等级/置信度/爬坡极端拐点)
  const resource = wxQc.passed.length
    ? buildResourceSignal(wxQc.passed, cascade)  // 标 T1/T5/T6 早期线索;置信度一路传导决定下游直通
    : undefined;
  if (resource) requireCalibration(resource, "新能源预测专责"); // rule 7 资源口径审定不可缺位

  // 步骤3 interpretInflowSignal —— 合格水文→来水信号,梯级滞时平移(rule 6)
  const inflow = hyQc.passed.length
    ? buildInflowSignal(hyQc.passed, shiftByLagTime(cascade)) // 汛期流速快滞时变短,按实测动态校正;防洪态势最金贵
    : undefined;
  if (inflow) requireCalibration(inflow, "水调专责");          // rule 7 来水口径审定不可缺位

  const result = persistInterpretation(ctx.caseId, resource, inflow); // 写 Interpretation_Result.signal_profile_96
  return { event: "DATA_INTERPRETED", result };
}

// OP-01 出力预测:DATA_INTERPRETED -> FORECAST_COMPLETED
// 域边界:慧采唯一入口取数据/可用容量;智调只产出预测,不下发(能控EMS管做)
async function forecastOutput(
  ctx: { caseId: string; coverDate: string; stations: Power_Station[]; operatingContext: Operating_Context },
  weather: Weather_Data[],          // 质控合格风光资源信号
  hydrology: Hydrology_Data[],      // 质控合格来水信号
  model: Forecast_Model,
): Promise<Output_Forecast> {
  // step1 fetchAvailableCapacity —— 设备通可用容量为上限,核同步心跳(rule 5 CR-UNIT-04)
  const units: Equipment[] = await deviceTong.queryAvailableCapacity(ctx.stations);
  const maint: Maintenance_Plan[] = await deviceTong.queryMaintenance(ctx.stations);
  if (deviceTong.syncStaleOver30min()) raiseAlarm("设备通可用容量同步超时"); // rule 5
  units.forEach(u => { if (scada.statusMismatch(u)) flag(u, "状态存疑"); }); // rule 5 一致性比对

  // step2 computeOutputForecast —— 按电站类型逐96点,出 P50/P90(rule 8)
  const fc: Output_Forecast = forecastEngine.compute(ctx.stations, weather, hydrology, units, maint, {
    timeScale: ctx.operatingContext.special_operating_mode ? "15min_0_4h" : "96pt",
    modelId: model.forecast_model_id, // 记录模型版本/合格率回评(rule 8)
  }); // forecast_mw_p50 / forecast_mw_p90 两条带,生成 FC 批次

  // step3 evaluateConfidence —— 置信度客观评定 + 可用容量钳制(rule 8/11/19)
  for (const u of units) {
    const cap = unitCapacity(u, maint); // 检修=0/受阻降额/故障=0
    if (fc.forecast_mw_p50[u.equipment_id] > cap) { clampToCapacity(fc, u, cap); fc.capacityClamped = true; } // rule 19 CR-UNIT-04
  }
  fc.accuracy_rate = confidence(weather, fc, model.offline_qualified_rate); // 信号置信度+区间宽度+历史合格率
  fc.lowConfidence = fc.accuracy_rate < 0.9; // <0.9 标低置信,直通条件③;禁止人工手调(rule 11)
  await huicai.persist(fc);
  return emit("FORECAST_COMPLETED", fc);
}

async function generateSuggestion(
  forecast: Output_Forecast,
  ctx: Operating_Context,
  gzl: Grid_Interface_Plan,
  stations: Power_Station[],
  equipment: Equipment[],
  sections: Grid_Section[],
): Promise<{ suggestion: Dispatch_Suggestion; bid: Market_Declaration; event: string }> {
  // 触发: FORECAST_COMPLETED 或 人工确认载荷=REJECTED(重新生成方案)

  // 步骤1 setDispatchObjective: 按运行方式季节标识设定三大目标优先级口径
  // rule 12 汛期 防洪>电网安全>消纳>经济; 非汛期 电网安全>经济/消纳>蓄能, 防洪类为硬约束
  const objective: Dispatch_Objective = setObjective(ctx.season_tag, ctx.special_operating_mode);

  // 步骤2 decomposeEnergyAndBuildCurve: 自上而下电量分解 + 编 96 点曲线
  // rule 13 关口送出贴 GZL.interface_curve_96 留约 2% 余量, 算 gate_deviation
  const gateCurve = alignToGZL(gzl.interface_curve_96, 0.02);
  // rule 14 风光优先消纳、水电调峰让路: 新能源 P50 先占额度, 水电填空; 断面受限按 stability_limit_mw 压水电给风光
  let curve = allocateRenewableFirst(forecast.forecast_mw_p50, equipment, sections);
  // 机组级先扣检修占用(available_mw)、安排开停机
  curve = scheduleUnitsOnOff(curve, equipment);
  // 龙头 ST0101 水位控制曲线按水量平衡联编自洽 (CR-HYD-01)
  const levelCtrl = buildLevelCurve(stations, forecast); // 出力↔出库↔水位自洽
  // rule 18 CR-UNIT-03 命中最小开停机时间/次数 → 转人工(机器不自动取消)
  // rule 21 CR-HYD-01 水位轨迹越上下限 → 升 T3 转人工(水位为推算不可直接钳)
  if (hitMinOnOff(curve, equipment) || levelOutOfLimit(levelCtrl, stations)) {
    return routeToManual(objective, gateCurve, curve, levelCtrl);
  }
  const gateDeviation = calcGateDeviation(gateCurve, gzl.interface_curve_96);

  // 步骤3 deriveMarketBid: 出力曲线换算市场申报量价
  // 现货申报量 = 关口送出 − 中长期合约分解电量; 中长期按月→日→96点分解
  // rule 33 CR-MKT-01 量价超上下限/合约冲突 → 钳制到合规区间
  const bid: Market_Declaration = clampToMarketBand(deriveBid(gateCurve));

  const suggestion = persistSuggestion({ objective, curve, gateCurve, levelCtrl, bid, gateDeviation });
  return { suggestion, bid, event: "SUGGESTION_GENERATED" };
}

// action id=5 validateConstraints — 主链路第④段·五组约束校验(OP-03)
// 触发:SUGGESTION_GENERATED;产出:CONSTRAINT_VALIDATED
async function validateConstraints(
  suggestion: Dispatch_Suggestion,
  rules: Constraint_Rule[],
  equipment: Equipment[],
  stations: Power_Station[],
  sections: Grid_Section[],
  market: Market_Declaration,
): Promise<{ payload: string; redline: boolean; hits: Constraint_Hit[] }> {
  // rule 35:关口计划 GZL / 断面限额等红线判据缺失则挂起不放行
  if (!gridInterfacePlanReady() || !sections.every(s => s.stability_limit_mw))
    return suspendCase("missing_redline_judgement");

  // step1 runConstraintEngine — rule 15 固定顺序 机组→水库→电网→安全→市场
  const ordered = sortByGroup(rules, ["CR-UNIT", "CR-HYD", "CR-GRID", "CR-SAFE", "CR-MKT"]);
  let hits: Constraint_Hit[] = runEngine(suggestion, ordered, { equipment, stations, sections, market }); // rule 16/19/21/26/30/33

  // step2 clampSoftAndHard — 软约束提示优化、普通硬约束钳制留痕
  for (const h of hits) {
    if (h.hard_soft === "soft") promptOptimize(h);                 // rule 17/34 振动区/偏差考核带
    else if (!h.is_redline) { clampToLimit(suggestion, h); auditTrace(h); } // rule 16/22/36 记前值后值
  }
  if (rampSmoothed(suggestion)) hits = reRunGridHydro(suggestion, ordered); // rule 20 平滑后重过后续约束

  // step3 flagRedlineViolation — rule 45 红线不可钳制消除者强制转人工
  const redlineHits = hits.filter(h => h.is_redline); // CR-HYD-05/CR-HYD-03/CR-GRID-01/CR-GRID-03/CR-SAFE-02
  const redline = redlineHits.length > 0;
  if (redline) { markRedline(suggestion, redlineHits); routeToManual(suggestion); } // rule 38 一票拔高等级

  persistHits(hits); // rule 36 命中/调整/分流全程留痕入 Audit_Event
  const payload = redline ? "HIT_HARD_REDLINE" : "VALIDATED_WITH_CLAMP";
  return emit("CONSTRAINT_VALIDATED", { payload, redline, hits });
}

// OP-04 主链路第⑤段:方案比选 + 风险标注
// 域边界:智调管"想"(出方案/比选);能控EMS管"做";外部数据经慧采唯一入口
async function compareSchemes(
  suggestion: Dispatch_Suggestion,          // CONSTRAINT_VALIDATED 通过的基线建议
  payload: string,                          // 须="校验通过(含可接受钳制)"
  ctx: Operating_Context,                   // 汛/非汛 -> 消纳/经济权重
  objective: Dispatch_Objective,            // 优先级顺序与硬目标
): Promise<Scheme_Comparison> {
  // 守门:仅对校验通过(含可接受钳制)案件比选
  if (payload !== "校验通过(含可接受钳制)") throw new Error("非可比选载荷,不进入比选");

  // 步骤1 buildSchemeMatrix:汇总生成 2-3 套候选方案与比选矩阵
  const candidates: Dispatch_Suggestion[] =
    buildCandidateSchemes(suggestion, objective); // 防洪裕度优先/消纳最大/经济最优
  const matrix = buildComparisonMatrix(candidates);

  // 步骤2 scoreByPriority:按 rule 12 三大目标优先级权重打分
  const weights = resolvePriorityWeights(ctx, objective); // 汛期消纳>经济
  for (const c of candidates) {
    if (hitsRedline(c)) { c.objective_score = -Infinity; continue; } // 红线一票否决出局
    // 经济性打分=市场收益−偏差考核罚款(rule 34 CR-MKT-02)
    c.objective_score = weightedScore(matrix, c, weights);
  }
  const ranked = candidates.filter(c => c.objective_score > -Infinity)
                           .sort((a, b) => b.objective_score - a.objective_score);
  const recommended = ranked[0];
  const isClearlyDominant = ranked.length < 2 ||
    (ranked[0].objective_score - ranked[1].objective_score) > DOMINANCE_GAP; // 直通条件⑤

  // 步骤3 tagSchemeRisk:rule 37 多约束命中按同一隐患归集→定 T1-T8/L1-L4
  const riskEvents: Risk_Event[] = candidates.map(c =>
    classifyRisk(aggregateHits(c)));          // 避免一隐患报一堆 RK

  // 落库比选结果 + 留痕,触发 SCHEMES_COMPARED
  const comparison = await saveSchemeComparison({
    dispatch_case_id: suggestion.dispatch_case_id,
    compared_suggestions: candidates.map(c => c.dispatch_suggestion_id),
    comparison_matrix: matrix,
    recommended_suggestion_id: recommended.dispatch_suggestion_id,
    is_clearly_dominant: isClearlyDominant,
  });
  await emitEvent("SCHEMES_COMPARED", { comparison, riskEvents });
  return comparison;
}

// OP-05 分流判断 triageScheme:输入 SCHEMES_COMPARED,产出单一事件 ROUTING_DECIDED
async function triageScheme(
  cmp: Scheme_Comparison,
  rec: Dispatch_Suggestion,
  fc: Output_Forecast,
  risks: Risk_Event[],
  gzl: Grid_Interface_Plan,
  ctx: Operating_Context,
  kase: Dispatch_Case,
): Promise<{ routing: "AUTO_ADOPTED" | "ROUTED_TO_MANUAL" }> {
  // 步骤1 evaluateDirectPass:逐条判五条直通条件(rule 41,AND 关系,3.0%/0.9 踩线按超阈保守)
  const REDLINES = ["CR-HYD-05", "CR-HYD-03", "CR-GRID-01", "CR-GRID-03"]; // 四条硬约束红线
  const c1 = Math.abs(rec.gate_deviation) <= 0.03;                 // ① 关口偏差≤3%(对齐 gzl)rule 42
  const c2 = !risks.some(r => r.risk_level >= "L2");               // ② 无 L2 及以上风险 rule 43
  const c3 = fc.accuracy_rate >= 0.9;                               // ③ 出力预测置信度(P50合格率)≥0.9 rule 44
  const c4 = !risks.some(r => REDLINES.includes(r.hit_constraint_id)); // ④ 无硬约束红线命中 rule 45
  const c5 = cmp.is_clearly_dominant === true;                     // ⑤ 方案明显占优 rule 46
  const evidence = { c1, c2, c3, c4, c5 };
  // 切换期/特殊运行方式强制不直通(纪律红线:不得手动绕过分流)
  const forcedManual = !!ctx.special_operating_mode || ctx.is_maintenance_mode;
  const directPass = c1 && c2 && c3 && c4 && c5 && !forcedManual;
  // 步骤2 routeDecision:全满足→AUTO_ADOPTED;否则→ROUTED_TO_MANUAL 并按风险等级派单
  if (directPass) {
    await businessSystem.setStatus(kase.dispatch_case_id, "AUTO_ADOPTED"); // rule 63 理想路径
    rec.is_recommended = true;
    // 步骤3 snapshotDirectPass:归档直通快照,审计留痕不可删(rule 74)
    await audit.archiveSnapshot(kase.dispatch_case_id, { type: "DIRECT_PASS", evidence });
    await notify("值班调度员", "工作台", "案件直通自动采纳,见直通快照");
    return { routing: "AUTO_ADOPTED" };
  }
  const maxLv = highestLevel(risks);                                // L3→值长 L4→值长+总工
  await businessSystem.createManualApproval(kase.dispatch_case_id, maxLv); // 进人工复核工作台
  await businessSystem.setStatus(kase.dispatch_case_id, "MANUAL_REVIEW");
  await audit.log(kase.dispatch_case_id, "ROUTED_TO_MANUAL", evidence);
  return { routing: "ROUTED_TO_MANUAL" };
}

// OP-05 人工确认(第二道防线):仅处理 ROUTED_TO_MANUAL 案件,人拍板、机留痕
async function manualConfirm(
  caseObj: Dispatch_Case,
  risks: Risk_Event[],
  suggestion: Dispatch_Suggestion,
  rules: Constraint_Rule[],
  confirmer: Role,
): Promise<{ event: "MANUAL_REVIEW_DECIDED"; conclusion: string }> {
  // 守门:仅转人工案件进入(切换期/特殊方式亦经此路)
  if (caseObj.status !== "MANUAL_REVIEW") throw new Error("非转人工案件");

  // step1 assignByRiskLevel — 按最高风险等级分派并改派 owner(rule 47 逐级不越级)
  const lvl = maxRiskLevel(risks);              // L1..L4
  const stage = assignStage(lvl);               // L3→值长 / L4→值长+总工+上报省调
  caseObj.owner_id = reassignOwner(stage);
  if (lvl === "L3" || lvl === "L4") { caseObj.is_suspended = true; markSuspended(risks); } // rule 48

  // step2 reviewConfirmation — 确认六看 + 红线拦截(rule 45/55)
  const redline = rules.some(r => r.is_redline); // 防洪/生态/关口/大坝
  assertPermission(confirmer, lvl);              // 调度员不得采纳 L3/L4(rule 73)
  const findings = sixLookReview(suggestion, rules, risks, redline);

  // step3 recordDecisionWithTrace — 本级权限内拍板 + 留痕三件套(rule 50/67/70)
  const ap = buildApproval(confirmer, stage, findings); // conclusion/opinion≥10/trace_before|after|reason
  if (!validTrace(ap)) throw new Error("留痕缺失,提交锁死"); // 理由空缺不予通过
  const conclusion = ap.conclusion; // MANUAL_CONFIRMED|RETURNED_FOR_REVISION|REJECTED|SUSPENDED
  caseObj.status = transitByConclusion(conclusion); // 退回→DRAFT / 否决→重生成

  // step4 escalateApprovalChain — 逐级不跳级、每级留签、加签不分摊(rule 53/54)
  if (needEscalate(lvl, redline)) await escalateChain(caseObj, stage, confirmer); // 涉网回贴省调批复 rule55

  // step5 enforceTimeliness — 自分派并行计时,超时升级非降标准(KCP-19)
  startTimelinessTimer(caseObj, stage); // 调度员→值长→总工,L4 超时惊动总工+主任

  writeAudit(caseObj, "MANUAL_REVIEW_DECIDED", conclusion); // 审计不可删 rule70
  return { event: "MANUAL_REVIEW_DECIDED", conclusion };
}

// OP-06 计划定版:直通采纳 / 人工确认采纳 / 暂缓解除三路汇合后锁定 DP
async function finalizePlan(
  kase: Dispatch_Case,             // 目标案件
  suggestion: Dispatch_Suggestion, // 采纳(调整后)的建议
  gzl: Grid_Interface_Plan,        // 省调关口计划(权威判据)
  payload: "AUTO_ADOPTED" | "MANUAL_CONFIRMED" | "风险闭环可恢复"
): Promise<{ plan: Dispatch_Plan; finalized: boolean }> {
  // 入口分支:仅三种采纳载荷可进入定版,退回/否决不归本动作
  if (!["AUTO_ADOPTED", "MANUAL_CONFIRMED", "风险闭环可恢复"].includes(payload))
    throw new Error("non-adopt payload: route elsewhere");

  // step1 lockDispatchPlan —— 按采纳曲线固化 DP 各字段并置 PLANNED (rule 56 OP-06)
  const plan: Dispatch_Plan = await BusinessSystem.lockPlan({
    dispatch_case_id: kase.dispatch_case_id,
    plan_type: kase.plan_type,
    cover_date: suggestion.cover_date,
    station_output_96: suggestion.station_output_96,
    unit_onoff: suggestion.unit_dispatch,
    level_control: suggestion.water_level_ctrl,
    gate_curve: suggestion.gate_output_96,
    market_bid: suggestion.market_bid,
    status: "PLANNED",           // 定版即锁,智调侧只读,改走 OP-11
  });

  // step2 verifyGateAlignment —— 关口送出逐时段不超 GZL (rule 29 / 72 CR-GRID-03)
  if (!gzl?.interface_curve_96)
    return haltNoGZL(plan);        // 缺 GZL 校验挂起不放行,绝不自动改关口
  const aligned = plan.gate_curve.every(
    (v, t) => v <= gzl.interface_curve_96[t]    // 逐点不得超送
  );
  if (!aligned) return blockFinalize(plan);     // 冲突→不得定版,转人工按红线处置

  // 回填案件并落审计,触发 PLAN_FINALIZED 推进 OP-07 回写 EMS
  await DispatchCase.bind({ id: kase.dispatch_case_id, dispatch_plan_id: plan.dispatch_plan_id, status: "PLANNED" });
  await Audit.trace(kase.dispatch_case_id, "PLAN_FINALIZED");
  return { plan, finalized: true };
}

// OP-07 postToEMS:智调非控域 → 能控EMS控制域 唯一有序交接点
async function postToEMS(
  plan: Dispatch_Plan,            // 定版/滚动修正 DP(status 应为 PLANNED)
  ems: Business_System,          // 能控EMS:对外唯一出口(rule 57)
  gzl: Grid_Interface_Plan,      // 省调关口计划,校核判据(CR-GRID-03)
  units: Equipment[],            // 机组可用容量,校核判据(CR-UNIT-04)
  dsCase: Dispatch_Case,         // 关联案件,承接状态流转与审计
  trigger: "AUTO" | "MANUAL_REPUSH",
  lastConfirmerId: string,
): Promise<{ event: "POSTED_TO_EMS" | null }> {
  // 前置:必须已定版,绝不跳过定版直接改 EMS 执行值
  if (plan.status !== "PLANNED") throw new Error("DP 未定版,禁止回写");
  if (!gzl?.interface_curve_96) return { event: null }; // 缺 GZL 挂起不放行(rule 29)

  // step1 postPlanToEms:96 点逐点一致、单向有序回写(rule 57 OP-07 唯一出口)
  const ack = await emsApi.postPlan(ems, {
    planId: plan.dispatch_plan_id, version: plan.version,
    output96: plan.station_output_96, onoff: plan.unit_onoff,
    level: plan.level_control, gate: plan.gate_curve, bid: plan.market_bid,
  });

  // step2 emsSecondaryCheck:关口≤GZL / 出力≤可用容量 / 版本一致,不过拦回
  const overGate = exceedsGzl(plan.gate_curve, gzl.interface_curve_96);     // CR-GRID-03
  const overCap  = exceedsCapacity(plan.station_output_96, units);          // rule 19 CR-UNIT-04
  if (overGate || overCap || ack.version !== plan.version) {
    await audit.write(dsCase, { event_type: "回写EMS拦回", actor_type: "EMS",
      trace_detail: { overGate, overCap, versionMismatch: ack.version !== plan.version } });
    return { event: null }; // 拦回,不放行下游
  }

  // step3 attachWritebackTrace:回贴 DS 审计链、状态转 POSTED(rule 74 留痕不可删)
  dsCase.status = "POSTED"; // 控制权移交能控EMS
  await audit.write(dsCase, { event_type: "回写EMS", actor_type: trigger === "AUTO" ? "Agent" : "Human",
    operator_id: lastConfirmerId, from_status: "PLANNED", to_status: "POSTED",
    trace_detail: { time: now(), trigger } });
  return { event: "POSTED_TO_EMS" };
}

// OP-12 市场申报回写:基于定版 DP 生成现货/中长期申报量价,经能控EMS报出交易中心(智调不直连)
// 触发: PLAN_FINALIZED  产出事件: MARKET_DECLARED
async function declareMarket(
  plan: Dispatch_Plan,                 // 定版 DP(PLANNED+),gate_curve/market_bid 锁定只读
  gzl: Grid_Interface_Plan,            // 省调关口计划 GZL,校核口径
  emsOut: Business_System,             // 能控EMS:唯一对外出口
  declType: "SPOT" | "MTL",            // 申报类型(现货/中长期)
  deadline: Date,
): Promise<Market_Declaration> {
  // 前置:DP 须已定版,gate_curve 锁定;非定版直接拒绝(改动须走 OP-11)
  if (plan.status !== "PLANNED" && plan.status !== "EXECUTING")
    throw new Error("DP 未定版,OP-12 不得申报");

  // 步骤1 buildMarketDeclaration:量来自关口送出,现货=关口送出−中长期合约分解
  let bid = (declType === "SPOT")
    ? deriveSpotBid(plan.gate_curve, plan.market_bid)   // 现货量价 96 点
    : decomposeMtlBid(plan.market_bid);                 // 中长期月→日→点
  // 报价策略:必发/风光报低价保消纳,可调电量择高价(在 deriveSpotBid 内)
  // rule 33 CR-MKT-01:量价钳制到上下限/合约电量合规区间
  bid = clampToMktRule01(bid, plan.market_bid);
  // 红线:经济性优先级最低,绝不为抢市场破关口/防洪 → 校核不超送/欠送 GZL
  assertNotBreakGate(bid, gzl.interface_curve_96);

  // 步骤2 submitToExchange:硬门,现货截止前必须报出,过期作废只进偏差考核
  if (declType === "SPOT" && Date.now() > deadline.getTime())
    return persistVoid(plan, bid, "过期作废:量锁定只进偏差考核");
  // rule 61 OP-12:经能控EMS转交易中心接口报出,智调不直连交易中心
  const declaredAt = await emsOut.submitToExchange(bid, declType);

  // 落库 Market_Declaration + 留痕,emit MARKET_DECLARED
  return persistDeclaration(plan, bid, declType, declaredAt); // status=已报出
}

// OP-08 指令下发:控制域(能控EMS)动作,智调管想、能控EMS管做、慧采唯一入口
// trigger: POSTED_TO_EMS 且到执行时刻 -> emit DISPATCHED
async function dispatchInstruction(
  plan: Dispatch_Plan,            // 已回写EMS的定版计划
  equipments: Equipment[],       // 含 agc_ramp_rate / available_mw / status
  stations: Power_Station[],     // 含 grid_section_id
  ems: Business_System,          // 能控EMS:唯一对外执行出口
  currentSlot: number            // 当前96点时段序号
): Promise<{ instructions: Dispatch_Instruction[]; caseStatus: string }> {
  // 红线:智调不直接下令;仅 EMS 执行(rule 58 OP-08 由能控EMS执行)
  if (!ems.is_internal || ems.role_in_flow !== "对外执行出口") throw new Error("非能控EMS出口禁止下发");
  // 锁定历史段:只按当前时段及未来计划值下发,已执行段不可改
  const targetSlots = plan.station_output_96.slice(currentSlot);

  const instructions: Dispatch_Instruction[] = [];
  for (const eq of equipments) {
    const targetMw = lookupPlannedValue(plan, eq.equipment_id, currentSlot); // DP 当前时段计划值
    // rule 20 CR-UNIT-05:相邻时段变化超 AGC 爬坡率 -> 平滑爬坡 + 越限告警
    const ramped = clampByRampRate(targetMw, eq.agc_ramp_rate, eq.available_mw);
    if (ramped.violated) emitAlert("CR-UNIT-05", eq.equipment_id, ramped); // 平滑后须重过电网/水库约束
    // 分钟级下发 AGC/AVC/开停机令(贴计划跟踪频率与断面潮流)
    instructions.push(await ems.issue({
      dispatch_plan_id: plan.dispatch_plan_id,
      equipment_id: eq.equipment_id,
      power_station_id: eq.power_station_id,
      instruction_type: resolveType(eq, plan.unit_onoff), // AGC / AVC / 开停机
      target_value: ramped.value,
      issued_by_system_id: ems.business_system_id,
      dispatched_at: now(), status: "ISSUED",
    }));
  }
  // rule 28 CR-GRID-02:并网点母线电压/无功越限 -> AVC 自动调整并告警
  checkBusVoltageReactive(stations) && emitAlert("CR-GRID-02", null, null);

  await recordAudit(plan.dispatch_case_id, "DISPATCH", instructions);   // 全程留痕
  return { instructions, caseStatus: setCaseStatus(plan, "DISPATCHED") }; // -> DISPATCHED/EXECUTING
}

// OP-09 执行反馈回采与监盘:控制域 → 智调域回流,闭合三尺度
// 触发事件 DISPATCHED;产出事件 EXECUTION_FEEDBACK(供 OP-11 rollingRevision)
async function captureExecution(
  plan: Dispatch_Plan,               // 执行中的 DP(station_output_96/gate_curve/level_control)
  gzl: Grid_Interface_Plan,          // 省调关口送出计划(interface_curve_96,权威基准)
  stations: Power_Station[],         // 覆盖电站
  equipments: Equipment[],           // 机组状态/可用容量
  section: Grid_Section,             // 送出断面稳定限额
  huicai: Business_System            // 慧采:唯一数据入口(SCADA 接入)
): Promise<{ feedback: Execution_Feedback; event: string }> {
  // 域边界红线:实际出力一律经慧采/SCADA 回采,智调不直采、不直接下令(rule 59)
  assert(huicai.role_in_flow === "DATA_ENTRY");

  // step1 captureActualOutput:慧采/SCADA 回采各机组实际出力,实际 vs 计划逐点比对
  const actual96 = await scadaCapture(huicai, plan.dispatch_plan_id, stations, equipments);
  const pointDeviation96 = diffPerPoint(actual96, plan.station_output_96); // 回流智调供复盘
  const feedback: Execution_Feedback = createExecutionFeedback({
    dispatch_plan_id: plan.dispatch_plan_id,
    actual_output_96: actual96,
    actual_gate_energy: sumGateEnergy(actual96, plan.gate_curve),
    source_system: huicai.business_system_id,   // 真相源=慧采/SCADA
    feedback_time: now(),
  });

  // step2 monitorRealtime:调度员监盘"三看"——出力/水位/关口(本体只做呈现+异常识别,不决策)
  const gateBreach = exceedsLimit(feedback.actual_gate_energy, gzl.interface_curve_96, section.stability_limit_mw);
  const unitTrip = equipments.some(e => e.status === "TRIPPED");           // rule 62 指令执行纪律
  const anomaly = gateBreach || unitTrip || detectFreqEvent(actual96);
  if (anomaly) flagFourStepInitial(feedback);   // 稳住→定级→转人立 RK→留痕,交下游 Human 应急流

  // 偏差累积超带 → 标记日内滚动修正信号(关联 CR-MKT-02、T6/T7)
  const bandBreach = deviationBandBreached(pointDeviation96); // CR-MKT-02
  if (bandBreach) markRollingSignal(plan.dispatch_case_id);

  await writeAuditEvent(feedback, "EXECUTION_FEEDBACK_CAPTURED"); // 留痕不可删
  return { feedback, event: "EXECUTION_FEEDBACK" };              // 供 OP-11 承接
}

// OP-11 日内滚动计划修正(横切):智调管想,能控EMS管做,慧采唯一入口
async function rollingRevision(
  currentPlan: Dispatch_Plan,
  rollingCase: Dispatch_Case,
  feedback?: Execution_Feedback,
  risk?: Risk_Event,
  forecast?: Output_Forecast,
): Promise<{ revisedPlan: Dispatch_Plan; event: "PLAN_ROLLED" }> {
  // step1 triggerRolling: 节拍到 / 偏差持续>3%扩大 / T4·T5·T6·省调调GZL·新红线 / RISK_DISPOSED需滚动
  const gateExpanding = feedback ? isGateDeviationExpanding(feedback, currentPlan) : false; // 慧采回采实测
  const riskTriggers = risk ? ["T4", "T5", "T6"].includes(risk.risk_type) || isGzlChanged(risk) : false;
  const shouldRoll = isRollingTick() || gateExpanding || riskTriggers;
  if (!shouldRoll) return { revisedPlan: currentPlan, event: null /* 未触发滚动,不广播 PLAN_ROLLED */ }; // 不满足不滚动
  // rule 60: 只覆盖当前执行点之后的未来未执行时段,已执行段锁死
  const windowStart = currentExecutionPoint() + 1;

  // step2 reRunPipelineFuture: 不另开新 DS,仅改 windowStart 之后,重走精简六段
  const futureSlice = sliceFuture(currentPlan.station_output_96, windowStart);
  const revisedSuggestion: Dispatch_Suggestion = await runCompactPipeline(
    rollingCase, futureSlice, forecast, // 数据解释→超短期预测→建议修正(修正 vs 维持日前)→约束校验→比选
  );
  const routing = await fastTriage(revisedSuggestion); // 快速分流:直通或快速人工确认(rule 41 直通五条件)
  if (routing === "ROUTED_TO_MANUAL") await awaitQuickManualConfirm(rollingCase.dispatch_case_id);

  // step3 finalizeRevision: 计划号不变、版本号递增,前值/后值/理由留痕(rule 67 三件套)
  const revisedPlan: Dispatch_Plan = {
    ...currentPlan,
    version: currentPlan.version + 1, // 号不变、版本递增
    station_output_96: mergeLockedHistory(currentPlan.station_output_96, revisedSuggestion.station_output_96, windowStart),
    status: "PLANNED",
  };
  assertTraceTriplet(revisedSuggestion); // rule 67 理由≥10字,空缺不予通过
  await writeAuditEvent(rollingCase.dispatch_case_id, "PLAN_ROLLED", { trace_before: futureSlice, trace_after: revisedPlan.station_output_96 });
  // emit PLAN_ROLLED → postToEMS(OP-07)经能控EMS重新下发(智调不直连EMS)
  return { revisedPlan, event: "PLAN_ROLLED" };
}

// OP-10 偏差复盘与运行分析:实际 vs 计划偏差 + 追因(不算账只算偏差是违规)
async function analyzeDeviation(
  feedback: Execution_Feedback,            // 能控EMS经慧采回采的实测侧
  plan: Dispatch_Plan,                     // 已执行计划(计划侧,只读)
  forecast: Output_Forecast,               // 计划背后的预测,用于 T6 区分
  relatedRisks: Risk_Event[],              // 关联风险,用于 T7/安全让路区分
): Promise<Deviation_Report> {
  // 守域边界:执行反馈必须来自慧采(SCADA回采),非慧采来源拒绝
  if (!isFromHuicai(feedback.source_system) /* 源系统按 role 判定,与 captureExecution 一致 */) throw new Error("执行反馈非慧采入口,拒绝");

  // step1 computeDeviation —— rule 64:按96点算逐点偏差 + 关口整体偏差
  const pointDeviation96 = plan.station_output_96.map(
    (planMw, i) => feedback.actual_output_96[i] - planMw,
  );
  const gateDeviationRate = computeGateDeviationRate(
    feedback.actual_gate_energy, plan.gate_curve,
  ); // 整体超3% 或单点暴偏在此识别(时段/电站/机组类型)

  // step2 attributeRootCause —— rule 64 归因表 + rule 34 CR-MKT-02 偏差考核带
  let deviationCause: string;
  if (forecast.accuracy_rate < 0.9) deviationCause = "T6 预测不准→反哺预测模型/置信度算法";
  else if (isInflowResourceDeviation(forecast)) deviationCause = "T5 来水资源偏离→反哺数据质控";
  else if (isExecutionDrift(pointDeviation96)) deviationCause = "执行走样→反哺指令执行纪律";
  else if (isTemporaryConstraintChange(relatedRisks)) deviationCause = "T2 约束临时变化";
  else if (Math.abs(gateDeviationRate) > CR_MKT_02_BAND)
    deviationCause = "T7 市场偏差(超偏差考核带,区分安全让路/预测失误)"; // rule 34 软约束升 T7
  else deviationCause = "偏差在控,无主因";

  // 持续超带或经济损失大 -> 转人工复盘进运行分析(已执行时段如实进复盘,不进修正)
  const reviewEscalated =
    Math.abs(gateDeviationRate) > CR_MKT_02_BAND || estimateEconomicLoss(relatedRisks) > LOSS_TH;

  // 落偏差报告并留痕(trace 不可删),产出 DEVIATION_ANALYZED 交 OP 归档承接
  return saveDeviationReport({
    dispatch_plan_id: plan.dispatch_plan_id, dispatch_case_id: plan.dispatch_case_id,
    point_deviation_96: pointDeviation96, gate_deviation_rate: gateDeviationRate,
    deviation_cause: deviationCause,
    analysis_conclusion: buildConclusion(deviationCause, reviewEscalated),
    analyzed_at: now(),
  });
}

// action 16: archiveCase —— 全链路归档,触发 DEVIATION_ANALYZED,产出 ARCHIVED
// 智调管想(归档/审计回放);慧采唯一入口、能控EMS唯一出口;归档只固化不篡改
async function archiveCase(
  caseRef: Dispatch_Case,
  risks: Risk_Event[],
  approvals: Manual_Approval[],
  plan: Dispatch_Plan | null,
): Promise<{ status: string; pkg: ArchivePackage; event: "ARCHIVED" }> {
  // 入口校验:必须由偏差复盘完成事件驱动 (trigger=DEVIATION_ANALYZED)

  // step1 checkClosure —— 完结条件校验(rule 74 留痕不可删)
  const unclosed: string[] = [];
  // (a) 关联风险事件须已闭环或误报关闭、且不处暂缓
  for (const rk of risks) {
    if (rk.status !== "CLOSED" && rk.status !== "FALSE_ALARM") unclosed.push(rk.risk_event_id);
    if (rk.is_suspended) unclosed.push(rk.risk_event_id); // SUSPENDED 须先解除(rule 48 闭环)
  }
  // (b) 案件本体暂缓须已解除
  if (caseRef.is_suspended) unclosed.push(`${caseRef.dispatch_case_id}:SUSPENDED`);
  // (c) 全链路动作齐(确认/回写/执行/复盘动作落在 trace_log)
  if (!hasFullChainActions(caseRef.trace_log, approvals, plan)) unclosed.push("CHAIN_INCOMPLETE");
  if (unclosed.length > 0) throw new ClosureNotMetError(unclosed); // 不予归档,退回处置

  // step2 archiveFullChain —— 固化全链路数据+日志,置 ARCHIVED
  const pkg = buildArchivePackage({          // 每事件时标+触发上下文、每 OP 经办人、每 AP 实例与状态机同步
    traceLog: caseRef.trace_log,             // rule 74:trace_log 不可删,只读固化
    approvals, risks, plan,
  });
  const from = caseRef.status;
  caseRef.status = "ARCHIVED";               // 状态置 ARCHIVED(智调侧只读归档,不再回改)

  // rule 67 + rule 74:归档动作落审计事件留痕三件套(谁/何时/前后值/理由≥10字)
  await auditEngine.write({                  // Audit_Event: from_status->to_status, trace_detail
    dispatch_case_id: caseRef.dispatch_case_id,
    event_type: "ARCHIVE", from_status: from, to_status: "ARCHIVED",
    trace_detail: pkg.checksum,
  });
  await caseRepo.persist(caseRef);           // 智调归档库落库,可回放可追溯,可回放可追溯
  return { status: caseRef.status, pkg, event: "ARCHIVED" };
}

// action 17 raiseRiskEvent —— 风险事件立项与定级(横切急刹车入口)
// 触发:CONSTRAINT_VALIDATED 载荷=命中硬约束红线 / EXECUTION_FEEDBACK 实时越界
async function raiseRiskEvent(
  hits: Constraint_Hit[],        // 本案约束命中(已按隐患归集)
  rules: Constraint_Rule[],      // 命中约束的规则定义
  kase: Dispatch_Case,           // 关联案件
): Promise<{ risk: Risk_Event; routing: string }> {
  // step1 createRiskEvent —— rule 39 命中≠风险:仅过异常分阈值或硬升风险约束才立 RK
  const triggering = hits.filter(h => h.hard_soft === "hard" || rules.find(r => r.constraint_rule_id === h.constraint_rule_id)?.is_redline);
  if (triggering.length === 0) return { risk: null, routing: "NO_RISK" }; // 软约束命中只提示/优化避让,不立 RK
  // rule 37 按同一隐患归集后再立一个 RK,记关联 DS/DP、命中 CR、证据(时段/数值/幅度/趋势)
  const risk: Risk_Event = await zhidiao.riskEngine.createRiskEvent({
    dispatch_case_id: kase.dispatch_case_id, dispatch_plan_id: kase.dispatch_plan_id,
    hit_constraint_id: triggering.map(h => h.constraint_hit_id).join(","),
    evidence: collectEvidence(triggering), status: "OPEN",
  });
  triggering.forEach(h => zhidiao.markHitRaised(h, risk.risk_event_id)); // 回填 risk_raised/risk_event_id

  // step2 classifyRisk —— 约束→类型映射定主类型 T1-T8;等级评分与红线下限取高
  risk.risk_type = mapConstraintToType(triggering, rules);          // 可标关联类型
  const baseLevel = scoreRiskLevel(triggering);                     // 异常评分
  const redlineFloor = redlineMinLevel(rules);                      // rule 38 生态/防洪/大坝 L3,断面/关口 L2
  risk.risk_level = maxLevel(baseLevel, redlineFloor);              // 红线不因幅度小降级
  if (isLowConfidence(triggering)) risk.evidence += "[存疑:优先核底层气象/水文/预测]"; // rule 40
  await zhidiao.riskEngine.classify(risk);

  // step3 suspendIfHigh —— rule 48 L3/L4 暂缓 SUSPENDED;rule 49 L4 必报省调
  let routing = "RECORD";
  if (risk.risk_level === "L3" || risk.risk_level === "L4") {
    risk.is_suspended = true;
    await zhidiao.setCaseStatus(kase, "SUSPENDED");                 // 智调管想:仅置暂缓,不下发执行
    kase.owner_id = reassignOwner(risk.risk_level);                 // L3→值长,L4→值长+总工
    if (risk.risk_level === "L4") { risk.reported_up = true; routing = "ESCALATE_SHENGDIAO"; } // 仅标需上报,真正上报走调度渠道
    else routing = "ESCALATE_SHIFT_LEADER";
  }
  return { risk, routing }; // 产出 RISK_EVENT_RAISED(T7 市场偏差有意孤岛不在此实时扇出)
}

async function handleFloodControl(
  risk: Risk_Event,            // T3 防洪风险(RISK_EVENT_RAISED 载荷)
  hydro: Hydrology_Data,       // 慧采实测/预报水文(唯一入口,只读)
  station: Power_Station,      // 含 flood_limit_level=1612m / 梯级 cascade
  plan: Dispatch_Plan,         // 受影响计划(level_control/gate_curve)
  dcase: Dispatch_Case,
  gzl: Grid_Interface_Plan,    // 省调关口计划,机器不得自动改
): Promise<{ event: "FLOOD_CONTROL_HANDLED" }> {
  // 步骤1 assessFloodSituation:研判汛情、分黄/橙/红 (rule 21 水位不可直接钳, rule 25 防洪)
  const level = max(hydro.water_level, forecastPeakLevel(hydro.forecast_range)); // 实测逼近汛限以实测为准
  const grade = level >= 1612 ? "红" : level >= 1611.5 ? "橙" : level >= 1610 ? "黄" : "观察";
  risk.risk_level = level > station.flood_limit_level ? "L4" : "L3"; // rule 25 逼近 L3 / 超汛限 L4

  // 步骤2 prereleaseAndCascade:预泄腾库 + 梯级滞时跟进(智调只算,出库下发走能控EMS)
  let prerelease = computePrerelease(hydro, station);
  prerelease = clampToOutflowLimit(prerelease, station);            // rule 22 CR-HYD-02 出库上限,超则先削弃水
  prerelease = enforceEcoFlow(prerelease, station);                 // rule 23 CR-HYD-03 生态流量,任何人不得越权放行
  const cascade = cascadeByLagTime(station, prerelease);            // rule 24 CR-HYD-04 上级出库=下级入库±区间±滞时
  assertGateSafety(prerelease, plan.gate_curve);                    // rule 32 CR-SAFE-02 大坝闸门启闭安全

  // 步骤3 escalateAndReport:定级暂缓 + 上报(rule 48 SUSPENDED, rule 49 L4 上报省调)
  risk.is_suspended = true; dcase.is_suspended = true; dcase.status = "SUSPENDED"; // rule 48
  dcase.owner_id = risk.risk_level === "L4" ? CHIEF_AND_SHIFT_LEADER : SHIFT_LEADER;
  await recordApproval(dcase, risk.risk_level);                     // Manual_Approval 逐级留签
  if (risk.risk_level === "L4") {
    risk.reported_up = true;                                        // rule 49 仅表示需上报
    prepareProvincialReportDraft(risk, gzl); risk.reported_up = true;                    // 值长+总工走调度渠道,请求放宽 GZL,不自动改
  }
  await writeAuditEvent(dcase, "FLOOD_CONTROL", risk.disposal_action); // 全程留痕不可删
  return { event: "FLOOD_CONTROL_HANDLED" };                        // 待批复+风险闭环才解除暂缓
}

// action 19 handleGridSecurity:电网越限(T2)/上级关口冲突(T8)应急处置
// 智调管想:压回诉求/对账/定级;限出力与改版回写经能控EMS,外部数据经慧采;触发 RISK_EVENT_RAISED,产出 GRID_SECURITY_HANDLED
async function handleGridSecurity(
  risk: Risk_Event,
  plan: Dispatch_Plan,
  section: Grid_Section,
  gzl: Grid_Interface_Plan,
  gridRule: Constraint_Rule,
  dsCase: Dispatch_Case,
): Promise<{ event: "GRID_SECURITY_HANDLED"; suspended: boolean; reportedUp: boolean }> {
  let reportedUp = false;

  // step1 limitOutputToSection —— T2 断面/通道越限:按最新限额限出力压回(rule 27 CR-GRID-01)
  if (risk.risk_type === "T2") {
    const limit = section.stability_limit_mw; // 核当前运行方式(含检修方式)最新限额,检修方式更紧
    // 限出力顺序:先压水电给风光腾空间,压不动再限风光(T1);记前值/后值留痕
    const clamped = clampSectionFlow(plan.station_output_96, limit);
    await emsRequestRevise(plan.dispatch_plan_id, clamped); // 回写经能控EMS;实时紧急可先行但事后立即补审批并报省调
    audit(dsCase, "T2_CLAMP", plan.gate_curve, clamped, "送出超断面稳定限额,限出力压回限额内");
  }

  // step2 reconcileGateWithProvince —— T8 关口超欠:一律以省调GZL为准(rule 29/72 CR-GRID-03)
  if (risk.risk_type === "T8") {
    const dev = compareGate(plan.gate_curve, gzl.interface_curve_96); // 超送/欠送偏差
    // 绝不自动改关口:超送压回GZL内并报备,欠送(如防洪拦蓄)报正当理由;变更唯一路径=申请省调批复新GZL
    prepareProvincialReportDraft(gzl.grid_interface_plan_id, dev, gzl.issuing_authority); /* 不自动调省调:报备草案交值长+总工经调度渠道 */
    audit(dsCase, "T8_RECONCILE", plan.gate_curve, gzl.interface_curve_96, "关口与省调GZL冲突,以省调为准并报备");
  }

  // step3 escalateNetwork —— 涉网定级:L3 暂缓视情况上报、L4 必报省调(rule 48/49/55)
  const suspended = risk.risk_level === "L3" || risk.risk_level === "L4";
  if (suspended) {
    dsCase.status = "SUSPENDED"; dsCase.is_suspended = true; // 待风险闭环或省调批复解除
    reportedUp = risk.risk_level === "L4"; // L4 必报,标 reported_up;真正上报由值长+总工走调度渠道
    risk.reported_up = reportedUp;
  }
  // 需调GZL/断面限额走涉网申请→省调批复;省调临时指令立即响应走 OP-11 滚动
  return { event: "GRID_SECURITY_HANDLED", suspended, reportedUp };
}

// OP-11 设备故障应急处置 handleEquipmentFault(T4,含 CR-SAFE-01/CR-UNIT-02)
// 触发:RISK_EVENT_RAISED 载荷=T4 设备风险;产出:EQUIPMENT_FAULT_HANDLED
async function handleEquipmentFault(
  risk: Risk_Event,                 // 立起的 T4 风险事件
  faulted: Equipment,               // 故障/受阻机组台账(设备通为准)
  maint: Maintenance_Plan | null,   // 检修受阻占用
  plan: Dispatch_Plan,              // 现行已定版计划
  gzl: Grid_Interface_Plan,         // 省调关口送出计划
): Promise<EquipmentFaultHandledEvent> {
  // 步骤1 updateAvailableCapacity:以设备通为唯一权威源更新可用容量
  const synced = await deviceTong.fetchEquipment(faulted.equipment_id); // 设备通-可用容量查询,核同步心跳
  let available = deductOccupied(synced.available_mw, maint?.available_mw_during); // 先扣检修受阻占用
  // rule 31 CR-SAFE-01 温升过载 / rule 17 CR-UNIT-02 群发振动 -> 设备安全第一紧急停运
  const emergencyStop = isSafetyRedline(risk) || isVibrationCluster(risk);
  if (emergencyStop) { available = 0; await emsAGC.emergencyStop(faulted.equipment_id); } // 能控EMS-OP-08 紧急停机,宁可弃水
  // rule 19 CR-UNIT-04:受阻钳降额值、故障/检修等同0
  await deviceTong.updateStatus(faulted.equipment_id, { status: emergencyStop ? "STOPPED" : synced.status, available_mw: available });

  // 步骤2 rescheduleOutput:按新可用容量上限重排未来未执行时段(rule 60 OP-11 只覆盖未来)
  const rolling = openRollingCase(plan.dispatch_case_id);             // OP-11 开日内滚动案
  const { output96, shortfall } = reschedule(plan.station_output_96, available); // 缺口由其他可用机组+备用补
  if (shortfall > 0) {                                                // 整站补不齐
    await routeToManual(rolling, "缺口落空:调关口/调梯级");            // 智调-分流引擎 转人工
    prepareProvincialReportDraft(gzl.grid_section_id, shortfall); /* 不自动调省调:短时偏差报备草案交值长+总工/经能控EMS转 */ // rule 29 CR-GRID-03 报备短时偏差,涉网以省调为准
  }
  // 影响关口/消纳或涉网/防洪/群发安全 -> 升 L3/L4,经闭环/SUSPENDED 解除后恢复
  const level = escalate(risk.risk_level, shortfall, emergencyStop);
  await disposeRisk(risk.risk_event_id, { risk_level: level, disposal_action: "设备故障处置+OP-11滚动", is_suspended: level >= "L3" });
  await audit.write(plan.dispatch_case_id, "EQUIPMENT_FAULT_HANDLED");  // 全程留痕不可删
  return emit("EQUIPMENT_FAULT_HANDLED", { rolling, output96, level });
}

// action 21: handleRenewableCurtailment —— T1 弃能/消纳不足人工应急处置
// 触发: RISK_EVENT_RAISED 载荷=T1; 产出: CURTAILMENT_HANDLED
async function handleRenewableCurtailment(
  risk: Risk_Event,            // 待处置 T1 风险事件
  plan: Dispatch_Plan,         // 现行计划(station_output_96/gate_curve/level_control)
  section: Grid_Section,       // 受阻断面(stability_limit_mw)
  gzl: Grid_Interface_Plan,    // 省调关口送出计划
  stations: Power_Station[],   // 梯级电站台账
): Promise<{ event: "CURTAILMENT_HANDLED" }> {
  assert(risk.risk_type === "T1");

  // 步骤1 attemptAbsorption: 少弃优先(rule14 风光优先消纳/水电调峰让路, rule27 CR-GRID-01)
  // 第1顺位令水电下压拦蓄(=蓄水不算弃),前提水位未顶汛限且守生态/出库限
  const hydro = stations.filter(s => s.regulation !== "径流").sort((a,b)=>a.cascade_order-b.cascade_order);
  for (const st of hydro) {
    const levelOk = projectLevel(st, plan) < st.flood_limit_level; // rule21 CR-HYD-01
    const ecoOk = checkEcoFlow(st, plan) /* rule23 CR-HYD-03 */ && checkOutflow(st, plan); // rule22 CR-HYD-02
    if (levelOk && ecoOk) pressDownAndStore(plan, st, section.stability_limit_mw);
  }
  cascadeReshuffle(plan, hydro);                 // 梯级腾挪
  await requestGateRelax(gzl);                   // 申请省调放宽关口(以省调为准, 不自改)
  const hydroAtTop = isHydroPressedToTop(plan, stations); // 水位顶汛限存不下

  // 步骤2 curtailAndRecord: 水电下压到顶仍消纳不了才弃风弃光(下策), 升 T1, 留痕(rule65)
  let record: CurtailRecord | null = null;
  if (hydroAtTop && residualSurplus(plan, section) > 0) {
    record = curtailRenewable(plan);             // 弃风弃光=下策
    record.cause = isFloodPrerelease(plan) ? "该弃(CR-HYD-05)" : "被迫弃(CR-GRID-01)"; // rule65
    risk.disposal_action = serialize(record); risk.disposer_id = currentOperator();
  }

  // 步骤3 escalateIfFloodConflict: 汛期不弃即超汛限破 CR-HYD-05 → 防洪优先该弃就弃(rule25)
  if (floodConflict(stations, plan)) {           // 逼近汛限 L3 暂缓 / 超汛限 L4 上报省调
    risk.is_suspended = (risk.risk_level === "L3" || risk.risk_level === "L4"); risk.reported_up = risk.risk_level === "L4";
  }
  if (record && isLargeOrFrequent(record)) flagT1Review(risk); // 量大/频繁立专项复盘

  await emsDispatch(plan);                        // 能控EMS 唯一出口执行限出力/腾挪
  risk.status = "DISPOSED";
  return { event: "CURTAILMENT_HANDLED" };
}

// action 22: switchOperatingMode —— 计划编制总开关,前置于比选/分流(Actor: Human,触发 OPERATING_MODE_CHANGE_DECLARED)
async function switchOperatingMode(
  decl: OperatingModeChangeDeclaration,      // 经慧采接入的变更声明
  ctx: Operating_Context,                    // 当前运行方式
  levelRule: Constraint_Rule,                // CR-HYD-01 水位上下限
  objective: Dispatch_Objective,            // 三大目标口径
  maint: Maintenance_Plan | null,           // 涉检修方式时
  headStation: Power_Station,               // 龙头 ST0101
  roles: Role[],                            // 总工/水调/复核人
): Promise<{ ctx: Operating_Context; event: "OPERATING_MODE_SWITCHED" }> {
  // 步骤1 updateModeFlag:据汛期公告/汛限起止日期/特殊方式更新标识,双人复核改对(切换期强制人工)
  requireDualReview(roles);                  // 季节标识改对须双人复核,智调不直通
  ctx.season_tag = decl.targetSeasonTag;
  ctx.calendar_type = decl.calendarType;
  ctx.special_operating_mode = decl.specialMode;
  ctx.is_maintenance_mode = decl.isMaintenance;

  // 步骤2 switchConstraintAndWeights:切 CR-HYD-01 上限参照 + 比选权重 + 目标口径(切换时点须总工+水调拍定)
  const isFlood = ctx.season_tag === "汛期";
  levelRule.threshold_value = { upper: isFlood ? 1612 : 1620, lower: 1580 }; // rule 21 下限恒守死水位 1580m,低于亦升 T3 转人工
  objective.priority_order = isFlood
    ? ["防洪安全", "电网安全", "清洁能源消纳", "经济性"]   // rule 12 汛期口径
    : ["电网安全", "经济性/消纳", "蓄能优化"];           // rule 12 非汛期口径
  requireManualTiming(roles, ["总工", "水调"]);          // 切换时点人工拍定,非系统自动;切换期不直通

  // 步骤3 arrangeMaintenanceMode:检修机降/置 0 可用容量、龙头机组避让汛期并会签
  if (maint) {
    clampAvailableCapacity(maint);                       // rule 19 CR-UNIT-04 检修=可用容量0则出力为0,不参与分配
    syncFromEquipmentLedger(maint);                      // rule 5 可用容量以设备通为准、状态一致性校验
    if (maint.power_station_id === headStation.power_station_id)
      requireCoSign(roles, ["水调", "总工"], avoidFloodWindow(headStation)); // 龙头检修避开防洪关键期并会签
  }

  return { ctx, event: "OPERATING_MODE_SWITCHED" }; // 报状态流转喇叭,下游按新口径运行
}

// action 23: handoverShift —— 交接班(五看+五交),Human 主导,触发于 SHIFT_CHANGE_DUE
// 域边界:慧采唯一入口取数 / 智调管想不下发 / 关口以省调 GZL 为准;留痕守 rule 74
async function handoverShift(evt: ShiftChangeDueEvent): Promise<ShiftHandedOverEvent> {
  // 守卫:必须由 SHIFT_CHANGE_DUE 触发,且交班/接班工号齐备(认工号不认脸)
  if (!evt.outgoingOperatorId || !evt.incomingOperatorId) throw new Error("交接班缺交/接班工号");

  // step1 reviewShiftStatus —— 交接“五看”,经慧采取最新实测,设备以设备通为准
  const reservoir: Hydrology_Data[] = await huicai.fetchLatestReservoir(evt.stationScope); // 看一:水位/蓄能/汛限裕度
  const equipment: Equipment[] = await sheBeiTong.queryAvailableCapacity(evt.stationScope); // 看二:available_mw/status
  const gatePlan: Grid_Interface_Plan = await huicai.fetchGridInterfacePlanGZL(evt.stationScope); // 看三:GZL interface_curve_96
  const openCases: Dispatch_Case[] = await zhidiao.listOpenCases(evt.stationScope);   // 看四:在途 DS(含日内滚动修正)
  const openRisks: Risk_Event[] = await zhidiao.listUnclosedRisks(evt.stationScope);  // 看五:未闭环 RK(关注 is_suspended/L3-L4)
  const snapshot = buildShiftSnapshot(reservoir, equipment, gatePlan, openCases, openRisks);

  // step2 handoverOpenItems —— 交接“五交”:在途 DS-DP、未闭环 RK、滚动修正、待办与省调沟通
  const activePlans: Dispatch_Plan[] = await zhidiao.listActivePlans(evt.stationScope); // 交二:生效/在途 DP
  const carriedItems = collectCarryOver(openCases, activePlans, openRisks); // 漏交未闭环风险=红线,必须全列
  const record = composeHandoverRecord(snapshot, carriedItems, evt.outgoingOperatorId, evt.incomingOperatorId);

  // 接班人逐项核对并签收;未签收不得闭合(责任未完成移交)
  const signedOff = await ui.requestReceiverSignoff(evt.incomingOperatorId, record);
  if (!signedOff) throw new Error("接班人未签收,交接未完成");

  // rule 74 全链路审计留痕不可删:交接记录入审计事件 + 各案件 trace_log
  await audit.appendEvent({ eventType: "SHIFT_HANDED_OVER", actorType: "Human",
    operatorId: evt.outgoingOperatorId, traceDetail: record }); // 不可删
  await zhidiao.appendCaseTrace(openCases.map(c => c.dispatch_case_id), record);

  // 产出状态流转喇叭:交接完成、责任移交接班人
  return { event: "SHIFT_HANDED_OVER", handoverRecord: record, receiverSignoff: true, carriedOverItems: carriedItems };
}

// action 24: assessForecastAccuracy —— 出力预测准确率事后回评闭环
// 域边界:智调只出考核结论与反哺建议;数据经慧采入、结果经能控EMS出
async function assessForecastAccuracy(
  forecast: Output_Forecast,        // 待回评 FC(P50/P90、预期置信度、模型版本)
  feedback: Execution_Feedback,     // 慧采回采的实际出力 actual_output_96
  model: Forecast_Model,            // 所用预测模型/版本
): Promise<{ accuracy_rate: number; rmse: number; feedback: object }> {
  // 触发校验:DEVIATION_ANALYZED 或周期考核;须有实际反馈方可比对
  if (!feedback.actual_output_96) throw new Error("缺执行反馈,无源可回评");

  // step1 backEvaluateAccuracy —— rule 66 实际逐点比 FC
  const p50 = forecast.forecast_mw_p50, band = forecast.forecast_mw_p90; // 误差带口径
  const qualified = countWithinBand(feedback.actual_output_96, p50, band); // 落带内算合格
  const accuracyRate = qualified / 96;                                     // 合格点数/96
  const rmse = computeRMSE(feedback.actual_output_96, p50);                // 惩罚大偏差/防正负对冲
  const expected = forecast.confidence;                            // 发布时预期置信度
  const confidenceGap = expected - accuracyRate;                          // “预期高实际低”最该警惕

  // step2 reviewByDimensionAndFeedback —— rule 9/10/66
  const dims = reviewByDimension(forecast, feedback, model);              // 电站/时间尺度/工况/版本
  let rootCause = "";
  if (accuracyRate < 0.9) rootCause = traceT5orT6(dims, confidenceGap);   // 0.9 门限=军令状
  // rule 10:仅反哺,不追溯重算历史 FC;rule 9:模型回退/上线权限在系统组,本步只出建议
  const modelFeedback = buildModelFeedback(model, dims, rootCause, confidenceGap);

  // 仅 update 回评指标,不改模型上线状态、不下发执行
  await updateOutputForecast(forecast.output_forecast_id, { accuracy_rate: accuracyRate, deviation: rmse });
  await appendForecastModelFeedback(model.forecast_model_id, modelFeedback); // 反哺建议留痕,系统组裁定
  await emitEvent("FORECAST_ACCURACY_ASSESSED", { forecast, accuracyRate, rmse, confidenceGap, dims });
  return { accuracy_rate: accuracyRate, rmse, feedback: modelFeedback };
}

// action 25 runOperationAudit —— 第三道防线·运行稽核与全链路审计(actor: Human 安全稽核)
// 域边界:智调管想、能控EMS管做、慧采唯一入口;稽核只看不批(rule 69 监督权/操作权分离)
async function runOperationAudit(
  archived: Dispatch_Case[],            // 归档案件总体
  trail: Audit_Event[],                 // 不可删全链路留痕(rule 74)
  approvals: Manual_Approval[],
  hits: Constraint_Hit[],
  risks: Risk_Event[],
  kcps: Key_Control_Point[],            // KCP-01~25 核对清单
  trigger: string,                      // ARCHIVED / 周期 / 异常事件
): Promise<{ paper: Audit_Working_Paper; findings: Audit_Finding[]; closeRate: number }> {
  // step1 sampleCases:周期 + 风险加权 + 事件触发三种组合抽样
  const sampled = sampleCases(archived, risks, trigger); // L4 必审100% / L3 约50% / 擦边偏差0.028·置信0.90~0.92重点 / 异常即审
  const paper = openWorkingPaper(sampled, "周期+风险加权+事件触发"); // rule 76 底稿必留(批次/人/范围/依据)

  // step2 auditFullChain:非现场全链路日志审 + KCP 抽查 + 必要现场核实
  const flags: ViolationFlag[] = [];
  for (const c of sampled) {
    checkStatusFlowNoDangling(c, trail);                 // 状态流转合规无悬空
    if (c.gate_deviation <= 0.03 && c.max_risk_level < "L2" && c.confidence >= 0.9)
      verifyDirectPassReallyMet(c, trail);               // 直通五条件判据 直通五条真满足(踩线保守)
    flags.push(...auditApprovalsNoOverreach(approvals, c)); // rule 73 越权八条红线 + 留痕真
    flags.push(...auditConstraintClamp(hits, c));        // 五组约束跑齐、钳制合理、偏差>3%追因
    flags.push(...auditRiskGrading(risks, c));           // 定级准、L3/L4 暂缓真、未闭环不得擅恢复
    auditAgainstKCP(c, kcps);                            // KCP-14/15/17/21 每周必抽,余抽查;必要现场核实
  }

  // step3 recordFindingAndClose:开发现→定级(四级/五档,涉网涉防洪从重)→回访闭环
  const findings = flags.map(f => raiseFinding(f, paper.audit_working_paper_id)); // rule 73 记入 Audit_Finding
  const closeRate = followUpAndClose(findings);          // rule 77 发现→整改→回访→闭环;屡查屡犯升级主任
  finalizeWorkingPaper(paper, findings, closeRate);      // 写无异常说明/整改摘要,回写 KCP-25 闭环率
  emit("AUDIT_COMPLETED");
  return { paper, findings, closeRate };
}

// action 26: maintainConstraintConfig —— 约束配置与维护(规则库"活"维护)
// 域边界:智调系统组管"配",不替业务确认案件;慧采唯一入口、能控EMS唯一出口
async function maintainConstraintConfig(
  rule: Constraint_Rule,           // 待维护的 CR-* 约束规则(前值底座)
  trigger: "AUDIT_COMPLETED" | "FORECAST_ACCURACY_ASSESSED" | "GZL_OR_MODE_CHANGE",
  proposed: { threshold_value?: number; is_redline?: boolean; default_action?: string; reason: string },
  operator: Role,                  // 系统组角色
  model?: Forecast_Model           // 准确率回评反哺时关联模型
): Promise<{ updated: Constraint_Rule; audit: Audit_Event; status: string }> {

  // rule 68 配置权与业务确认权分离:系统组可配规则,但绝不点案件采纳/确认
  if (operator.permission_confirm) throwDisciplineViolation("配置角色不得持业务确认权");

  // —— Step1 updateConstraintThresholds:按反哺/省调限额/方式变更更新阈值 ——
  // rule 71 基线硬阈值不可改:关口偏差≤3%、置信度≥0.9 无修改入口
  if (isBaselineHardThreshold(rule.check_point)) {
    return { updated: rule, audit: logAudit(operator, rule, "BASELINE_REJECT"), status: "REJECTED_BASELINE_LOCKED" };
  }
  // rule 75 配置变更必留理由:理由空缺视为无源可溯不予生效(写透:改哪条/原值新值/依据)
  if (!proposed.reason || proposed.reason.trim().length < 10) {
    return { updated: rule, audit: logAudit(operator, rule, "NO_REASON"), status: "REJECTED_NO_REASON" };
  }
  const before = { ...rule };                                  // 系统自动记前值
  const staged: Constraint_Rule = applyThresholdChange(rule, proposed); // 阈值/红线/默认动作

  // 准确率回评反哺:按模型合格率联动判定是否需调对应约束命中阈值
  if (trigger === "FORECAST_ACCURACY_ASSESSED" && model) reconcileWithModel(staged, model);

  // —— Step2 reviewAndVersionConfig:业务复核 + 版本留痕 ——
  await requireBusinessReview(staged, operator);              // 系统组配置不替业务确认
  // rule 52 误报关闭留痕:由误报反哺时须记"为什么判误报"供倒查
  if (trigger === "AUDIT_COMPLETED") recordFalsePositiveFeedback(staged, proposed.reason);
  const versioned = versionConfig(staged);                    // 版本号 + 生效时间

  // 全程留痕入审计事件(不可删):前值/后值/理由
  const audit = logAudit(operator, before, "CONFIG_CHANGE", versioned, proposed.reason);
  emitEvent("CONSTRAINT_CONFIG_UPDATED", versioned.constraint_rule_id);
  return { updated: versioned, audit, status: "VERSIONED_EFFECTIVE" };
}

// id=27 resolveRiskAndResume —— 风险闭环与暂缓解除回流(横切,Human 主导)
// 触发:FLOOD_CONTROL_HANDLED / GRID_SECURITY_HANDLED / EQUIPMENT_FAULT_HANDLED / CURTAILMENT_HANDLED
type DisposalConclusion = "CLOSED_RESUMABLE" | "KEEP_SUSPENDED" | "FALSE_ALARM_CLOSED" | "REJECTED_REDO";
async function resolveRiskAndResume(
  risk: Risk_Event, kase: Dispatch_Case, role: Role,
  handledEvent: string, closureBasis: string
): Promise<{ payload: string; event: "RISK_DISPOSED" }> {
  // 步骤1 verifyRiskClosure —— 值长/总工核闭环/误报/批复(rule 48 解除权限 L3=值长、L4=值长+总工)
  assertConfirmPermission(role, risk.risk_level); // L3→值长, L4→值长+总工,否则越权(rule 73①②)
  if (closureBasis.trim().length < 10) throw new Error("闭环/误报依据须≥10字(留痕可溯)");
  let conclusion: DisposalConclusion;
  if (isFalseAlarm(risk)) {
    conclusion = "FALSE_ALARM_CLOSED";       // rule 52 误报关闭须记误报理由并留痕,反哺阈值
    risk.status = "FALSE_ALARM_CLOSED";
  } else if (risk.risk_level === "L4" && !hasProvinceApproval(risk)) {
    risk.reported_up = true;                  // rule 49 L4 必经值长+总工审定并真实上报省调
    conclusion = "KEEP_SUSPENDED";            // 未取得批复→维持暂缓等批复
  } else if (passedRevalidation(kase)) {
    conclusion = "CLOSED_RESUMABLE"; risk.status = "CLOSED";
  } else conclusion = "REJECTED_REDO";        // 隐患未消/方案不可行→否决重做
  risk.disposal_action = closureBasis; risk.disposer_id = role.role_id;

  // 步骤2 liftSuspensionAndRoute —— 解除 SUSPENDED 并按载荷路由(rule 48 凭闭环依据/省调答复才解除)
  let payload: string;
  if (conclusion === "CLOSED_RESUMABLE") { lift(kase, risk); payload = needFutureEdit(kase) ? "需滚动修正→rollingRevision" : "风险闭环可恢复→finalizePlan"; }
  else if (conclusion === "FALSE_ALARM_CLOSED") { lift(kase, risk); payload = "误报关闭→按当前点解冻恢复主链路"; }
  else { kase.status = "SUSPENDED"; payload = conclusion === "KEEP_SUSPENDED" ? "维持暂缓→等上级批复" : "否决重做→重新生成方案"; }
  // rule 73⑧/KCP-24 未闭环擅自恢复属越权;rule 74/KCP-20 解除恢复进审计事件不可删
  appendAuditEvent(kase, { event_type: "RISK_DISPOSED", operator_id: role.role_id, trace_detail: payload });
  return { payload, event: "RISK_DISPOSED" };
}

// action 28: validateAndDeploySystemChange —— 智调系统变更上线测试与部署(SDLC 治理,流程外横切)
// 触发: CONSTRAINT_CONFIG_UPDATED(阈值/规则变更) 或 SYSTEM_CHANGE_REQUESTED(软件升级/接入新电站机组)
async function validateAndDeploySystemChange(
  targetSystem: Business_System,           // 受测智调系统及配置管理模块
  tester: Role, configAdmin: Role, devTeam: Role,
  affectedStations: Power_Station[], affectedEquipment: Equipment[],
  forecastRef: Output_Forecast, schemeRef: Scheme_Comparison,
): Promise<{ deployDecision: string; testCaseSetVersion?: string }> {
  // step1 runPipelineWalkthrough: 据《测试用例集》对六段流水线端到端走查 (rule 78)
  const segments = ["数据解释","出力预测","调度建议生成","约束校验","方案比选+风险标注","人工确认+回写"];
  const walkthrough = await testTool.runPipelineWalkthrough(targetSystem, segments, { forecastRef, schemeRef, tester });

  // step2 returnOnTestFailure: 任一验收项与预期不符 -> 退回开发组修复后回归 (rule 80)
  const failures = walkthrough.items.filter(i => i.actual !== i.expected);
  if (failures.length > 0) {
    await collabTool.returnToDevTeam(targetSystem, devTeam, failures); // 修复->回归闭环
    return { deployDecision: "RETURNED" };
  }

  // step3 syncTestCasesAndBaseline: 涉规则/阈值/新设备 -> 同步用例+递增版本+更新电站/设备基线 (rule 81)
  let testCaseSetVersion: string | undefined;
  if (changeTouchesRuleThresholdOrDevice(affectedStations, affectedEquipment)) {
    testCaseSetVersion = await configTool.bumpTestCaseSet(configAdmin);          // 外部版本规范递增
    await configTool.updateBaseline(configAdmin, affectedStations, affectedEquipment);
  }

  // step4 gateDeployByCoverage: 配置管理模块按覆盖完整性拦截,缺覆盖禁止上线 (rule 79)
  const coverageOk = await configTool.checkCoverage(targetSystem, segments); // 任一段缺覆盖=false
  if (!coverageOk) return { deployDecision: "BLOCKED" };                      // 工程层自动拦截

  await configTool.deployToProduction(targetSystem);
  await emit("SYSTEM_CHANGE_DEPLOYED");                                       // 仅治理智调自身,不向EMS下发
  return { deployDecision: "DEPLOYED", testCaseSetVersion };
}
